def get_drive_account_by_name(self, name: str) -> dict:
    """
    Retrieve a drive account by its display name.

    Args:
        name (str): The display name of the drive account to look up.

    Returns:
        dict: On success, {"success": True, "data": DriveAccountInfo}.
              On failure, {"success": False, "error": str}.

    Constraints:
        - Performs a read-only lookup.
        - Matches the account name exactly.
    """
    for drive_account in self.drive_accounts.values():
        if drive_account["name"] == name:
            return {"success": True, "data": drive_account}

    return {"success": False, "error": "Drive account not found"}

def get_drive_account_by_id(self, drive_id: str) -> dict:
    """
    Retrieve a drive account by its drive_id.

    Args:
        drive_id (str): The unique identifier of the drive account.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": DriveAccountInfo
            }
        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The drive_id must reference an existing drive account.
        - This operation is read-only and does not modify system state.
    """
    drive_account = self.drive_accounts.get(drive_id)
    if drive_account is None:
        return {"success": False, "error": "Drive account not found"}

    return {"success": True, "data": drive_account}

def list_drive_accounts(self) -> dict:
    """
    List all connected drive accounts.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[DriveAccountInfo]
            }

            If the backing collection is unavailable or invalid, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - This is a read-only query.
        - No permission checks are required.
        - Returns an empty list when no drive accounts are connected.
    """
    try:
        accounts = list(self.drive_accounts.values())
        return {"success": True, "data": accounts}
    except Exception:
        return {"success": False, "error": "Unable to list drive accounts"}

def get_folder_by_id(self, folder_id: str) -> dict:
    """
    Retrieve folder metadata by folder_id.

    Args:
        folder_id (str): Unique identifier of the folder to look up.

    Returns:
        dict: On success, {"success": True, "data": FolderInfo}.
              On failure, {"success": False, "error": <reason>}.

    Constraints:
        - This operation is read-only and must not modify system state.
        - The folder_id must refer to an existing folder.
    """
    if not isinstance(folder_id, str) or not folder_id:
        return {"success": False, "error": "Invalid folder_id"}

    folder = self.folders.get(folder_id)
    if folder is None:
        return {"success": False, "error": "Folder not found"}

    return {"success": True, "data": folder}

def find_folder_by_path(self, drive_id: str, path: str) -> dict:
    """
    Resolve a folder by drive ID and full path.

    Args:
        drive_id (str): The drive account identifier to search within.
        path (str): The folder path to resolve.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": FolderInfo
            }
            On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The lookup is performed against stored folder metadata.
        - The folder must belong to the specified drive and match the path exactly.
    """
    for folder in self.folders.values():
        if folder["drive_id"] == drive_id and folder["path"] == path:
            return {"success": True, "data": folder}

    return {"success": False, "error": "Folder not found"}

def list_child_folders(self, parent_folder_id: str) -> dict:
    """
    List immediate subfolders under a given parent folder.

    Args:
        parent_folder_id (str): The folder ID whose direct children should be returned.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[FolderInfo]
            }
        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The parent folder must exist.
        - Only immediate children are returned, not nested descendants.
    """
    if parent_folder_id not in self.folders:
        return {"success": False, "error": "Parent folder does not exist"}

    child_folders = [
        folder_info
        for folder_info in self.folders.values()
        if folder_info["parent_folder_id"] == parent_folder_id
    ]

    return {"success": True, "data": child_folders}

def get_file_by_id(self, file_id: str) -> dict:
    """
    Retrieve file metadata by file_id.

    Args:
        file_id (str): The unique identifier of the file to retrieve.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": FileInfo
            }
        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The file_id must reference an existing file in the drive system.
        - This operation is read-only and does not modify state.
    """
    if not file_id:
        return {"success": False, "error": "File not found"}

    file_info = self.files.get(file_id)
    if file_info is None:
        return {"success": False, "error": "File not found"}

    return {"success": True, "data": file_info}

def find_file_by_name(self, drive_id: str, folder_id: str, name: str) -> dict:
    """
    Find files by name within a specified drive and folder scope.

    Args:
        drive_id (str): The ID of the drive account to search within.
        folder_id (str): The ID of the folder to search within.
        name (str): The file name to match exactly.

    Returns:
        dict: On success, {"success": True, "data": List[FileInfo]} where the list
        contains all files matching the given drive, folder, and name scope.
        On failure, {"success": False, "error": str}.

    Constraints:
        - The drive_id must reference an existing drive account.
        - The folder_id must reference an existing folder.
        - Matching is exact on drive_id, folder_id, and name.
        - An empty match set is a successful result.
    """
    if drive_id not in self.drive_accounts:
        return {"success": False, "error": "Drive account does not exist"}

    folder = self.folders.get(folder_id)
    if folder is None:
        return {"success": False, "error": "Folder does not exist"}

    if folder["drive_id"] != drive_id:
        return {"success": False, "error": "Folder does not belong to the specified drive"}

    matches = [
        file_info
        for file_info in self.files.values()
        if file_info["drive_id"] == drive_id
        and file_info["folder_id"] == folder_id
        and file_info["name"] == name
    ]

    return {"success": True, "data": matches}

def list_files_in_folder(self, folder_id: str) -> dict:
    """
    List all files stored in a given folder.

    Args:
        folder_id (str): The ID of the folder to inspect.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[FileInfo]
            }
            where the list contains all files whose folder_id matches the input.
            If the folder exists but contains no files, the list is empty.

            On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The folder must exist in self.folders.
        - This operation does not modify state.
    """
    if folder_id not in self.folders:
        return {"success": False, "error": "Folder does not exist"}

    files_in_folder = [
        file_info
        for file_info in self.files.values()
        if file_info["folder_id"] == folder_id
    ]

    return {"success": True, "data": files_in_folder}

def get_file_current_version(self, file_id: str) -> dict:
    """
    Retrieve the current version reference for a file.

    Args:
        file_id (str): The unique identifier of the file.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": Optional[FileVersionInfo]
            }
            where data is the current version record for the file, or None if the file
            has no current version assigned.

        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The file must exist in the drive system.
        - If a current_version_id is present, it must reference an existing file version.
        - This operation does not modify state.
    """
    file_info = self.files.get(file_id)
    if file_info is None:
        return {"success": False, "error": "File does not exist"}

    current_version_id = file_info.get("current_version_id")
    if current_version_id is None:
        return {"success": True, "data": None}

    version_info = self.file_versions.get(current_version_id)
    if version_info is None:
        return {"success": False, "error": "Current version reference is missing"}

    return {"success": True, "data": version_info}

def list_file_versions(self, file_id: str) -> dict:
    """
    List the version history for a file in chronological order.

    Args:
        file_id (str): The identifier of the file whose versions should be listed.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[FileVersionInfo]
            }
            The list is ordered by version_number ascending.
            On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The file must exist in the drive before its versions can be listed.
        - Version history is returned in chronological order, using version_number as the primary ordering key.
        - If the file has no versions, the result is an empty list.
    """
    if file_id not in self.files:
        return {"success": False, "error": "File does not exist"}

    versions = [
        version
        for version in self.file_versions.values()
        if version.get("file_id") == file_id
    ]

    versions.sort(key=lambda v: v.get("version_number", 0))

    return {"success": True, "data": versions}

def get_file_version_by_id(self, version_id: str) -> dict:
    """
    Retrieve metadata for a specific file version.

    Args:
        version_id (str): Identifier of the file version to retrieve.

    Returns:
        dict: On success:
            {
                "success": True,
                "data": FileVersionInfo
            }
            On failure:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The requested version_id must exist in self.file_versions.
        - This is a read-only query and does not modify system state.
    """
    if not version_id:
        return {"success": False, "error": "version_id is required"}

    version = self.file_versions.get(version_id)
    if version is None:
        return {"success": False, "error": "File version not found"}

    return {"success": True, "data": version}

def get_sharing_setting_by_target(self, target_id: str, target_type: str) -> dict:
    """
    Retrieve the sharing setting for a file or folder.

    Args:
        target_id (str): The ID of the file or folder to look up.
        target_type (str): The target kind, expected to be either "file" or "folder".

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": Optional[SharingSettingInfo]
            }
            The data value is None if no sharing setting exists for the target.

        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - target_type must be either "file" or "folder".
        - The referenced file or folder must exist.
        - Sharing settings are read-only for this query and do not modify state.
    """
    if target_type not in {"file", "folder"}:
        return {"success": False, "error": "Invalid target_type; expected 'file' or 'folder'"}

    if target_type == "file":
        if target_id not in self.files:
            return {"success": False, "error": "File does not exist"}
        for sharing_setting in self.sharing_settings.values():
            if sharing_setting["file_id"] == target_id:
                return {"success": True, "data": sharing_setting}
    else:
        if target_id not in self.folders:
            return {"success": False, "error": "Folder does not exist"}
        for sharing_setting in self.sharing_settings.values():
            if sharing_setting["folder_id"] == target_id:
                return {"success": True, "data": sharing_setting}

    return {"success": True, "data": None}

def list_sharing_settings(self) -> dict:
    """
    List all sharing settings in the drive.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": List[SharingSettingInfo]
            }
            The list is empty if no sharing settings exist.

        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - This is a read-only query and must not modify system state.
        - No target file or folder is required.
    """
    try:
        return {
            "success": True,
            "data": list(self.sharing_settings.values()),
        }
    except Exception:
        return {
            "success": False,
            "error": "Failed to list sharing settings",
        }

def get_conversion_job_by_id(self, job_id: str) -> dict:
    """
    Retrieve the status and details of a conversion job by its job ID.

    Args:
        job_id (str): The identifier of the conversion job to retrieve.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": ConversionJobInfo
            }
        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The conversion job must exist in self.conversion_jobs.
        - This is a read-only query and must not modify system state.
    """
    job = self.conversion_jobs.get(job_id)
    if job is None:
        return {"success": False, "error": "Conversion job not found"}

