def list_conversion_jobs_by_source_file(self, source_file_id: str) -> dict:
    """
    List all conversion jobs associated with a given source file.

    Args:
        source_file_id (str): The file_id of the source file whose conversion jobs
            should be listed.

    Returns:
        dict: On success:
            {
                "success": True,
                "data": List[ConversionJobInfo]
            }
            On failure:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - The source file must exist in the drive.
        - Returns an empty list if the file has no conversion jobs.
    """
    if source_file_id not in self.files:
        return {"success": False, "error": "Source file does not exist"}

    jobs = [
        job for job in self.conversion_jobs.values()
        if job["source_file_id"] == source_file_id
    ]

    return {"success": True, "data": jobs}

def get_export_artifact_by_id(self, artifact_id: str) -> dict:
    """
    Retrieve a derived export artifact by its artifact_id.

    Args:
        artifact_id (str): Unique identifier of the export artifact to retrieve.

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": ExportArtifactInfo
            }
            On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - This is a read-only lookup.
