        self.conversion_jobs: Dict[str, ConversionJobInfo] = {}

        # ExportArtifact: artifact_id, source_file_id, generated_file_id, artifact_type, format, location_id, created_at
        self.export_artifacts: Dict[str, ExportArtifactInfo] = {}

        # Constraints:
        # - Every file belongs to exactly one drive account and one folder at a time.
        # - Folder hierarchy is tree-structured through parent_folder_id, with a single root per drive.
        # - File names are scoped by folder and drive rules, and renames must preserve file identity.
        # - Conversion jobs reference an existing source file and produce a target format compatible with the workflow.
        # - Derived conversion output is tracked separately from the source file and may create a new file version or a new file artifact.
        # - Sharing settings apply to files or folders and constrain access but do not change the underlying file content.
        # - Version history must preserve the lineage of edits and generated artifacts.

    def get_drive_account_by_name(self, name: str) -> dict:
