    def create_folder(
        self,
        drive_id: str,
        parent_folder_id: Optional[str],
        name: str
    ) -> dict:
        """
        Create a new folder under a specified parent folder within a drive.

        Args:
            drive_id (str): ID of the drive account that will own the folder.
            parent_folder_id (Optional[str]): ID of the parent folder, or None for a root-level folder
                when supported by the drive model.
            name (str): Name of the new folder.

        Returns:
            dict: On success:
                { "success": True, "message": "Folder created successfully" }
            On failure:
                { "success": False, "error": str }

        Constraints:
            - The drive must exist.
            - If parent_folder_id is provided, it must exist and belong to the same drive.
            - Folder names must be unique within the same parent scope for a drive.
            - The folder hierarchy must remain tree-structured.
        """

        if not drive_id or drive_id not in self.drive_accounts:
            return {"success": False, "error": "Drive account does not exist"}

        if not name or not name.strip():
            return {"success": False, "error": "Folder name is required"}

        name = name.strip()

        parent_path = ""
        if parent_folder_id is not None:
            parent_folder = self.folders.get(parent_folder_id)
            if parent_folder is None:
                return {"success": False, "error": "Parent folder does not exist"}
            if parent_folder["drive_id"] != drive_id:
                return {"success": False, "error": "Parent folder belongs to a different drive"}
            parent_path = parent_folder["path"].rstrip("/")
        else:
            # Root-level folder under the drive.
            root_folder_id = self.drive_accounts[drive_id]["root_folder_id"]
            if root_folder_id and root_folder_id in self.folders:
                parent_path = self.folders[root_folder_id]["path"].rstrip("/")
            else:
                parent_path = ""

        # Enforce unique folder name within the same parent scope on the same drive.
        for folder in self.folders.values():
            if folder["drive_id"] != drive_id:
                continue
            if folder["parent_folder_id"] == parent_folder_id and folder["name"] == name:
                return {"success": False, "error": "Folder name already exists in the target location"}

        folder_id = str(uuid.uuid4())
        timestamp = datetime.now(timezone.utc).isoformat()

        if parent_path:
            path = f"{parent_path}/{name}"
        else:
            path = f"/{name}"

        self.folders[folder_id] = {
            "folder_id": folder_id,
            "drive_id": drive_id,
            "parent_folder_id": parent_folder_id,
            "name": name,
            "path": path,
            "created_at": timestamp,
            "updated_at": timestamp,
        }

        return {"success": True, "message": "Folder created successfully"}

    def rename_folder(self, folder_id: str, new_name: str) -> dict:
        """
        Rename a folder while preserving its identity and hierarchy.

        Args:
            folder_id (str): The identifier of the folder to rename.
            new_name (str): The new folder name.

        Returns:
            dict: On success, {"success": True, "message": "Folder renamed successfully"}.
                  On failure, {"success": False, "error": "<reason>"}.

        Constraints:
            - The folder must exist.
            - The new name must be non-empty after trimming whitespace.
            - Folder names must be unique among siblings within the same drive and parent folder.
            - Folder identity (folder_id) must not change.
            - If the folder has descendants, their paths must be updated consistently.
            - Root folder renaming is treated as invalid unless explicitly supported by the current state model.
        """
        folder = self.folders.get(folder_id)
        if folder is None:
            return {"success": False, "error": "Folder not found"}

        normalized_name = new_name.strip()
        if not normalized_name:
            return {"success": False, "error": "New folder name cannot be empty"}

        if folder.get("parent_folder_id") is None:
            return {"success": False, "error": "Root folder cannot be renamed"}

        parent_folder_id = folder.get("parent_folder_id")
        drive_id = folder["drive_id"]

        for other_folder_id, other_folder in self.folders.items():
            if other_folder_id == folder_id:
                continue
            if (
                other_folder["drive_id"] == drive_id
                and other_folder.get("parent_folder_id") == parent_folder_id
                and other_folder["name"] == normalized_name
            ):
                return {"success": False, "error": "A sibling folder with the same name already exists"}

        old_path = folder.get("path", "")
        old_name = folder["name"]
        folder["name"] = normalized_name

        parent_path = ""
        if parent_folder_id is not None:
            parent_folder = self.folders.get(parent_folder_id)
            if parent_folder is not None:
                parent_path = parent_folder.get("path", "").rstrip("/")

        if parent_path:
            folder["path"] = f"{parent_path}/{normalized_name}"
        else:
            folder["path"] = f"/{normalized_name}"

        for child_folder in self.folders.values():
            child_path = child_folder.get("path", "")
            if old_path and child_path.startswith(old_path.rstrip("/") + "/"):
                suffix = child_path[len(old_path.rstrip("/")):]
                child_folder["path"] = folder["path"].rstrip("/") + suffix

        folder["updated_at"] = folder.get("updated_at", "")

        return {"success": True, "message": "Folder renamed successfully"}

    def move_folder(self, folder_id: str, new_parent_folder_id: Optional[str]) -> dict:
        """
        Reparent a folder to another folder within the same drive.

        Args:
            folder_id (str): The ID of the folder to move.
            new_parent_folder_id (Optional[str]): The target parent folder ID, or None if
                moving to the drive root level.

        Returns:
            dict: On success, returns:
                {"success": True, "message": "Folder moved successfully"}
            On failure, returns:
                {"success": False, "error": "<reason>"}

        Constraints:
            - The folder must exist.
            - The new parent folder must exist if not None.
            - The folder and new parent must belong to the same drive.
            - The folder cannot be moved into itself or any of its descendants.
            - The drive root folder cannot be reparented.
            - Folder hierarchy must remain a tree.
        """
        if folder_id not in self.folders:
            return {"success": False, "error": "Folder not found"}

        folder = self.folders[folder_id]
        old_parent_id = folder["parent_folder_id"]

        if new_parent_folder_id == folder_id:
            return {"success": False, "error": "Folder cannot be moved into itself"}

        drive_id = folder["drive_id"]

        root_folder_id = None
        for account in self.drive_accounts.values():
            if account["drive_id"] == drive_id:
                root_folder_id = account["root_folder_id"]
                break

        if root_folder_id is not None and folder_id == root_folder_id:
            return {"success": False, "error": "Root folder cannot be moved"}

        if new_parent_folder_id is not None:
            if new_parent_folder_id not in self.folders:
                return {"success": False, "error": "New parent folder not found"}

            new_parent = self.folders[new_parent_folder_id]
            if new_parent["drive_id"] != drive_id:
                return {"success": False, "error": "Cannot move folder across drives"}

            # Prevent cycles: new parent cannot be a descendant of the folder being moved.
            current_id = new_parent_folder_id
            while current_id is not None:
                if current_id == folder_id:
                    return {"success": False, "error": "Cannot move folder into its descendant"}
                current_id = self.folders[current_id]["parent_folder_id"]

        old_path = folder["path"]

        if new_parent_folder_id is None:
            new_path = "/" + folder["name"]
        else:
            parent_path = self.folders[new_parent_folder_id]["path"].rstrip("/")
            new_path = parent_path + "/" + folder["name"]

        now = datetime.now(timezone.utc).isoformat()

        folder["parent_folder_id"] = new_parent_folder_id
        folder["path"] = new_path
        folder["updated_at"] = now

        old_prefix = old_path.rstrip("/")
        new_prefix = new_path.rstrip("/")

        # Update descendant paths so the tree remains consistent.
        for descendant in self.folders.values():
            if descendant["folder_id"] == folder_id:
                continue
            descendant_path = descendant["path"].rstrip("/")
            if descendant_path.startswith(old_prefix + "/"):
                suffix = descendant_path[len(old_prefix):]
                descendant["path"] = new_prefix + suffix
                descendant["updated_at"] = now

        return {"success": True, "message": "Folder moved successfully"}

    def upload_file(
        self,
        drive_id: str,
        folder_id: str,
        file_id: str,
        name: str,
        mime_type: str,
        extension: str,
        size: int,
        checksum: str,
        created_at: str,
        uploaded_by: str,
        source_artifact_id: Optional[str] = None,
        version_id: Optional[str] = None,
    ) -> dict:
        """
        Create a new file in a folder and initialize its metadata and version linkage.

        Args:
            drive_id (str): ID of the drive account that will own the file.
            folder_id (str): ID of the destination folder.
            file_id (str): Unique ID for the new file.
            name (str): File name scoped within the destination folder.
            mime_type (str): MIME type of the uploaded file.
            extension (str): File extension.
            size (int): File size in bytes.
            checksum (str): Content checksum for deduplication/integrity.
            created_at (str): Creation/upload timestamp.
            uploaded_by (str): Identifier of the user or system actor creating the file.
            source_artifact_id (Optional[str]): Optional source artifact linkage for derived uploads.
            version_id (Optional[str]): Optional version ID to use for the initial version.

        Returns:
            dict: On success, {"success": True, "message": "File uploaded successfully"}.
                  On failure, {"success": False, "error": "<reason>"}.

        Constraints:
            - The target folder must exist and belong to the specified drive.
            - file_id must be unique across all files.
            - File names must be unique within the same drive/folder scope.
            - If provided, source_artifact_id should reference a known artifact.
            - The created file becomes the current version owner if an initial version is created.
        """
        if drive_id not in self.drive_accounts:
            return {"success": False, "error": "Drive account does not exist"}

        folder = self.folders.get(folder_id)
        if folder is None:
            return {"success": False, "error": "Folder does not exist"}

        if folder["drive_id"] != drive_id:
            return {"success": False, "error": "Folder does not belong to the specified drive"}

        if file_id in self.files:
            return {"success": False, "error": "File ID already exists"}

        for existing in self.files.values():
            if existing["drive_id"] == drive_id and existing["folder_id"] == folder_id and existing["name"] == name:
                return {"success": False, "error": "File name already exists in the target folder"}

        if source_artifact_id is not None and source_artifact_id not in self.export_artifacts:
            return {"success": False, "error": "Source artifact does not exist"}

        if version_id is not None and version_id in self.file_versions:
            return {"success": False, "error": "Version ID already exists"}

        file_info: FileInfo = {
            "file_id": file_id,
            "drive_id": drive_id,
            "folder_id": folder_id,
            "name": name,
            "mime_type": mime_type,
            "extension": extension,
            "size": size,
            "checksum": checksum,
            "created_at": created_at,
            "updated_at": created_at,
            "current_version_id": version_id,
        }
        self.files[file_id] = file_info

        if version_id is not None:
            version_number = 1
            for existing_version in self.file_versions.values():
                if existing_version["file_id"] == file_id and existing_version["version_number"] >= version_number:
                    version_number = existing_version["version_number"] + 1

            self.file_versions[version_id] = {
                "version_id": version_id,
                "file_id": file_id,
                "version_number": version_number,
                "mime_type": mime_type,
                "size": size,
                "created_at": created_at,
                "created_by": uploaded_by,
                "source_artifact_id": source_artifact_id,
            }

        return {"success": True, "message": "File uploaded successfully"}

    def rename_file(self, file_id: str, new_name: str) -> dict:
        """
        Rename a file while preserving its identity and all non-name metadata.

        Args:
            file_id (str): Identifier of the file to rename.
            new_name (str): New file name to assign.

        Returns:
            dict: On success,
                {"success": True, "message": "File renamed successfully"}
                On failure,
                {"success": False, "error": "<reason>"}

        Constraints:
            - The file must exist.
            - `new_name` must be a non-empty string.
            - File names must remain unique within the same drive and folder scope.
            - Renaming must not change file_id, drive_id, folder_id, or version lineage.
        """
        file_info = self.files.get(file_id)
        if file_info is None:
            return {"success": False, "error": "File does not exist"}

        if not isinstance(new_name, str) or not new_name.strip():
            return {"success": False, "error": "New file name must be a non-empty string"}

        normalized_new_name = new_name.strip()
        drive_id = file_info["drive_id"]
        folder_id = file_info["folder_id"]

        for other_file_id, other_file in self.files.items():
            if other_file_id == file_id:
                continue
            if other_file["drive_id"] == drive_id and other_file["folder_id"] == folder_id and other_file["name"] == normalized_new_name:
                return {"success": False, "error": "A file with the same name already exists in this folder"}

        file_info["name"] = normalized_new_name

        # Preserve identity and metadata lineage; only the name changes.
        # Use a simple write-time update when available in the file record.
        if "updated_at" in file_info:
            file_info["updated_at"] = file_info["updated_at"]

        return {"success": True, "message": "File renamed successfully"}

    def move_file(self, file_id: str, target_folder_id: str) -> dict:
        """
        Move an existing file to another folder while preserving its drive association and file identity.

        Args:
            file_id (str): Identifier of the file to move.
            target_folder_id (str): Identifier of the destination folder.

        Returns:
            dict: On success, returns:
                {"success": True, "message": "File moved successfully"}
            On failure, returns:
                {"success": False, "error": "<reason>"}

        Constraints:
            - The file must exist.
            - The target folder must exist.
            - The file and target folder must belong to the same drive.
            - File names must remain unique within the destination folder and drive scope.
            - The operation only changes folder assignment and preserves file identity.
        """
        file_info = self.files.get(file_id)
        if file_info is None:
            return {"success": False, "error": "File does not exist"}

        target_folder = self.folders.get(target_folder_id)
        if target_folder is None:
            return {"success": False, "error": "Target folder does not exist"}

        if file_info["drive_id"] != target_folder["drive_id"]:
            return {"success": False, "error": "Cannot move file across different drives"}

        if file_info["folder_id"] == target_folder_id:
            return {"success": True, "message": "File moved successfully"}

        target_name = file_info["name"]
        for other_file_id, other_file_info in self.files.items():
            if other_file_id == file_id:
                continue
            if (
                other_file_info["drive_id"] == file_info["drive_id"]
                and other_file_info["folder_id"] == target_folder_id
                and other_file_info["name"] == target_name
            ):
                return {
                    "success": False,
                    "error": "A file with the same name already exists in the target folder",
                }

        file_info["folder_id"] = target_folder_id
        return {"success": True, "message": "File moved successfully"}

    def delete_file(self, file_id: str) -> dict:
        """
        Remove a file and its active references according to drive rules.

        Args:
            file_id (str): Identifier of the file to delete.

        Returns:
            dict: On success, {"success": True, "message": "..."}.
                  On failure, {"success": False, "error": "..."}.

        Constraints:
            - The file must exist before it can be deleted.
            - All direct references to the file should be removed to avoid dangling state.
            - This operation does not enforce permissions because no auth model is defined here.
        """
        if file_id not in self.files:
            return {"success": False, "error": "File does not exist"}

        # Remove the file itself.
        del self.files[file_id]

        # Remove file versions tied to the deleted file.
        versions_to_delete = [
            version_id
            for version_id, version in self.file_versions.items()
            if version["file_id"] == file_id
        ]
        for version_id in versions_to_delete:
            del self.file_versions[version_id]

        # Remove sharing settings directly attached to the file.
        shares_to_delete = [
            share_id
            for share_id, share in self.sharing_settings.items()
            if share["file_id"] == file_id
        ]
        for share_id in shares_to_delete:
            del self.sharing_settings[share_id]

        # Remove conversion jobs that reference the file as input or output.
        jobs_to_delete = [
            job_id
            for job_id, job in self.conversion_jobs.items()
            if job["source_file_id"] == file_id or job["output_file_id"] == file_id
        ]
        for job_id in jobs_to_delete:
            del self.conversion_jobs[job_id]

        # Remove export artifacts sourced from the deleted file.
        artifacts_to_delete = [
            artifact_id
            for artifact_id, artifact in self.export_artifacts.items()
            if artifact["source_file_id"] == file_id
        ]
        for artifact_id in artifacts_to_delete:
            del self.export_artifacts[artifact_id]

        return {"success": True, "message": "File deleted successfully"}

    def create_file_version(
        self,
        version_id: str,
        file_id: str,
        version_number: int,
        mime_type: str,
        size: int,
        created_at: str,
        created_by: str,
        source_artifact_id: Optional[str] = None,
    ) -> dict:
        """
        Add a new version record for an existing file revision.

        Args:
            version_id (str): Unique identifier for the new file version.
            file_id (str): Identifier of the existing file to version.
            version_number (int): Version number for this revision.
            mime_type (str): MIME type for the version content.
            size (int): Size of the version in bytes.
            created_at (str): Creation timestamp for the version.
            created_by (str): Identifier of the user or system that created the version.
            source_artifact_id (Optional[str]): Optional export/conversion artifact lineage reference.

        Returns:
            dict: On success:
                {
                    "success": True,
                    "message": "File version created successfully"
                }
            On failure:
                {
                    "success": False,
                    "error": "<reason>"
                }

        Constraints:
            - The source file must exist.
            - The version_id must be unique.
            - The version_number must be unique per file.
            - If provided, source_artifact_id must reference an existing export artifact.
            - The file's current_version_id is updated to the new version.
        """
        if not version_id or not file_id or not mime_type or not created_at or not created_by:
            return {"success": False, "error": "Missing required parameters"}
        if version_number <= 0:
            return {"success": False, "error": "version_number must be positive"}
        if size < 0:
            return {"success": False, "error": "size must be non-negative"}

        if version_id in self.file_versions:
            return {"success": False, "error": "File version already exists"}

        file_info = self.files.get(file_id)
        if file_info is None:
            return {"success": False, "error": "Source file does not exist"}

        if source_artifact_id is not None and source_artifact_id not in self.export_artifacts:
            return {"success": False, "error": "Source artifact does not exist"}

        for existing_version in self.file_versions.values():
            if existing_version["file_id"] == file_id and existing_version["version_number"] == version_number:
                return {"success": False, "error": "Version number already exists for this file"}

        new_version: FileVersionInfo = {
            "version_id": version_id,
            "file_id": file_id,
            "version_number": version_number,
            "mime_type": mime_type,
            "size": size,
            "created_at": created_at,
            "created_by": created_by,
            "source_artifact_id": source_artifact_id,
        }

        self.file_versions[version_id] = new_version
        file_info["current_version_id"] = version_id
        file_info["updated_at"] = created_at

        return {"success": True, "message": "File version created successfully"}

    def update_file_metadata(
        self,
        file_id: str,
        name: Optional[str] = None,
        mime_type: Optional[str] = None,
        size: Optional[int] = None,
        checksum: Optional[str] = None,
    ) -> dict:
        """
        Update mutable metadata for an existing file.

        Args:
            file_id (str): Identifier of the file to update.
            name (Optional[str]): New file name. Must be non-empty if provided and
                unique within the same drive/folder scope.
            mime_type (Optional[str]): New MIME type. Must be non-empty if provided.
            size (Optional[int]): New file size in bytes. Must be a non-negative integer if provided.
            checksum (Optional[str]): New checksum value. Must be non-empty if provided.

        Returns:
            dict: On success, {"success": True, "message": "File metadata updated successfully"}.
                  On failure, {"success": False, "error": "<reason>"}.

        Constraints:
            - The file must exist.
            - Only mutable metadata fields are updated.
            - Renaming must preserve file identity and must not create duplicate names
              within the same folder and drive scope.
            - Does not modify sharing settings, versions, or folder membership.
        """
        file_info = self.files.get(file_id)
        if file_info is None:
            return {"success": False, "error": "File not found"}

        if name is None and mime_type is None and size is None and checksum is None:
            return {"success": False, "error": "No metadata fields provided for update"}

        if name is not None:
            if not isinstance(name, str) or not name.strip():
                return {"success": False, "error": "Invalid file name"}
            for other in self.files.values():
                if other["file_id"] != file_id and other["drive_id"] == file_info["drive_id"] and other["folder_id"] == file_info["folder_id"] and other["name"] == name:
                    return {"success": False, "error": "A file with the same name already exists in this folder"}

        if mime_type is not None:
            if not isinstance(mime_type, str) or not mime_type.strip():
                return {"success": False, "error": "Invalid MIME type"}

        if size is not None:
            if not isinstance(size, int) or size < 0:
                return {"success": False, "error": "Invalid file size"}

        if checksum is not None:
            if not isinstance(checksum, str) or not checksum.strip():
                return {"success": False, "error": "Invalid checksum"}

        if name is not None:
            file_info["name"] = name
            if "." in name:
                base_name, ext = name.rsplit(".", 1)
                file_info["extension"] = ext
            else:
                file_info["extension"] = ""

        if mime_type is not None:
            file_info["mime_type"] = mime_type

        if size is not None:
            file_info["size"] = size

        if checksum is not None:
            file_info["checksum"] = checksum

        # Best-effort timestamp update. If timestamps are stored as strings,
        # callers should provide an appropriate serialized value in the host system.
        file_info["updated_at"] = datetime.utcnow().isoformat() + "Z"

        self.files[file_id] = file_info
        return {"success": True, "message": "File metadata updated successfully"}

    def create_sharing_setting(
        self,
        share_id: str,
        file_id: Optional[str],
        folder_id: Optional[str],
        visibility: str,
        permissions: str,
        shared_with: List[str],
        link_enabled: bool,
    ) -> dict:
        """
        Create a sharing setting for either a file or a folder.

        Args:
            share_id (str): Unique identifier for the sharing setting.
            file_id (Optional[str]): Target file ID, or None if sharing a folder.
            folder_id (Optional[str]): Target folder ID, or None if sharing a file.
            visibility (str): Sharing visibility mode.
            permissions (str): Granted access permissions.
            shared_with (List[str]): List of users/groups/entities the target is shared with.
            link_enabled (bool): Whether link sharing is enabled.

        Returns:
            dict: On success, {"success": True, "message": "..."}.
                  On failure, {"success": False, "error": "..."}.

        Constraints:
            - Exactly one of file_id or folder_id must be provided.
            - The referenced file or folder must already exist.
            - share_id must be unique across sharing settings.
            - This operation only creates sharing metadata; it does not alter content.
        """
        if share_id in self.sharing_settings:
            return {"success": False, "error": "Sharing setting already exists"}

        has_file = file_id is not None
        has_folder = folder_id is not None
        if has_file == has_folder:
            return {
                "success": False,
                "error": "Exactly one of file_id or folder_id must be provided",
            }

        if has_file and file_id not in self.files:
            return {"success": False, "error": "Target file does not exist"}

        if has_folder and folder_id not in self.folders:
            return {"success": False, "error": "Target folder does not exist"}

        self.sharing_settings[share_id] = {
            "share_id": share_id,
            "file_id": file_id,
            "folder_id": folder_id,
            "visibility": visibility,
            "permissions": permissions,
            "shared_with": list(shared_with),
            "link_enabled": link_enabled,
        }

        return {"success": True, "message": "Sharing setting created successfully"}

    def update_sharing_setting(
        self,
        share_id: str,
        visibility: Optional[str] = None,
        permissions: Optional[str] = None,
        shared_with: Optional[List[str]] = None,
        link_enabled: Optional[bool] = None,
    ) -> dict:
        """
        Modify an existing sharing setting for a file or folder.

        Args:
            share_id (str): Identifier of the sharing setting to update.
            visibility (Optional[str]): New visibility setting, if provided.
            permissions (Optional[str]): New permissions setting, if provided.
            shared_with (Optional[List[str]]): New list of recipients, if provided.
            link_enabled (Optional[bool]): New link access state, if provided.

        Returns:
            dict: On success:
                { "success": True, "message": "Sharing setting updated" }
            On failure:
                { "success": False, "error": "<reason>" }

        Constraints:
            - The sharing setting must exist.
            - At least one updatable field must be provided.
            - This method updates only sharing attributes and does not change the target file/folder binding.
        """
        setting = self.sharing_settings.get(share_id)
        if setting is None:
            return {"success": False, "error": "Sharing setting not found"}

        if (
            visibility is None
            and permissions is None
            and shared_with is None
            and link_enabled is None
        ):
            return {"success": False, "error": "No update fields provided"}

        if visibility is not None:
            setting["visibility"] = visibility

        if permissions is not None:
            setting["permissions"] = permissions

        if shared_with is not None:
            setting["shared_with"] = shared_with

        if link_enabled is not None:
            setting["link_enabled"] = link_enabled

        self.sharing_settings[share_id] = setting
        return {"success": True, "message": "Sharing setting updated"}

    def delete_sharing_setting(self, share_id: str) -> dict:
        """
        Remove a sharing configuration from the system.

        Args:
            share_id (str): The identifier of the sharing setting to delete.

        Returns:
            dict: On success, returns:
                {
                    "success": True,
                    "message": "Sharing setting deleted successfully"
                }
                On failure, returns:
                {
                    "success": False,
                    "error": "<reason>"
                }

        Constraints:
            - The sharing setting must exist in self.sharing_settings.
            - This operation only removes the sharing record and does not alter file or folder content.
        """
        if share_id not in self.sharing_settings:
            return {"success": False, "error": "Sharing setting not found"}

        del self.sharing_settings[share_id]
        return {"success": True, "message": "Sharing setting deleted successfully"}

    def start_conversion_job(self, source_file_id: str, target_format: str) -> dict:
        """
        Create a conversion job for an existing source file and requested target format.

        Args:
            source_file_id (str): ID of the existing file to convert.
            target_format (str): Desired output format for the conversion job.

        Returns:
            dict: On success,
                {
                    "success": True,
                    "message": "Conversion job created",
                }
            On failure,
                {
                    "success": False,
                    "error": "reason"
                }

        Constraints:
            - The source file must exist.
            - The target format must be a non-empty string.
            - This operation creates only the conversion job record; it does not create the converted file.
        """

        if not source_file_id or source_file_id not in self.files:
            return {"success": False, "error": "Source file does not exist"}

        if not isinstance(target_format, str) or not target_format.strip():
            return {"success": False, "error": "Target format must be a non-empty string"}

        source_file = self.files[source_file_id]
        source_extension = source_file.get("extension", "").strip()
        source_mime_type = source_file.get("mime_type", "").strip()

        source_format = source_extension.lstrip(".").lower() if source_extension else ""
        if not source_format and source_mime_type:
            source_format = source_mime_type.lower()

        if not source_format:
            return {"success": False, "error": "Unable to determine source format from file metadata"}

        job_id = str(uuid.uuid4())
        while job_id in self.conversion_jobs:
            job_id = str(uuid.uuid4())

        now = datetime.now(timezone.utc).isoformat()

        self.conversion_jobs[job_id] = {
            "job_id": job_id,
            "source_file_id": source_file_id,
            "source_format": source_format,
            "target_format": target_format.strip().lower(),
            "status": "queued",
            "requested_at": now,
            "completed_at": None,
            "output_file_id": None,
            "error_message": None,
        }

        return {"success": True, "message": "Conversion job created"}

    def update_conversion_job_status(
        self,
        job_id: str,
        new_status: str,
        error_message: Optional[str] = None,
        completed_at: Optional[str] = None
    ) -> dict:
        """
        Update the status of an existing conversion job.

        Args:
            job_id (str): The ID of the conversion job to update.
            new_status (str): The new job status. Expected values are:
                'queued', 'running', 'completed', or 'failed'.
            error_message (Optional[str]): Error details required when setting status to
                'failed'. Ignored for non-failed terminal states.
            completed_at (Optional[str]): Optional timestamp to store when the job reaches
                a terminal state. If omitted for 'completed' or 'failed', the method may
                record the completion time using the current time representation available
                to the implementation.

        Returns:
            dict: On success, returns:
                { "success": True, "message": str }
            On failure, returns:
                { "success": False, "error": str }

        Constraints:
            - The job must exist.
            - The new status must be one of the supported workflow states.
            - Jobs already in terminal states ('completed', 'failed') are not updated.
            - A 'failed' status must include an error message.
            - Terminal states should set completed_at when not already provided.
        """
        if job_id not in self.conversion_jobs:
            return { "success": False, "error": "Conversion job does not exist" }

        allowed_statuses = {"queued", "running", "completed", "failed"}
        if new_status not in allowed_statuses:
            return {
                "success": False,
                "error": f"Invalid conversion job status: {new_status}"
            }

        job = self.conversion_jobs[job_id]
        current_status = job["status"]

        if current_status in {"completed", "failed"}:
            return {
                "success": False,
                "error": "Conversion job is already in a terminal state"
            }

        if new_status == "failed" and not error_message:
            return {
                "success": False,
                "error": "error_message is required when marking a job as failed"
            }

        job["status"] = new_status

        if new_status in {"completed", "failed"}:
            if completed_at is not None:
                job["completed_at"] = completed_at
            elif job["completed_at"] is None:
                try:
                    job["completed_at"] = datetime.utcnow().isoformat() + "Z"
                except Exception:
                    job["completed_at"] = ""
            if new_status == "failed":
                job["error_message"] = error_message
            else:
                job["error_message"] = None
        else:
            if new_status == "queued":
                job["completed_at"] = None
                job["error_message"] = None

        self.conversion_jobs[job_id] = job

        return {
            "success": True,
            "message": f"Conversion job {job_id} updated to status '{new_status}'"
        }

    def attach_conversion_output(
        self,
        job_id: str,
        output_file_id: Optional[str] = None,
        artifact_id: Optional[str] = None
    ) -> dict:
        """
        Record the converted output file and/or export artifact produced by a completed conversion job.

        Args:
            job_id (str): ID of the conversion job to update.
            output_file_id (Optional[str]): ID of the generated output file to attach, if any.
            artifact_id (Optional[str]): ID of the export artifact to associate with the job, if any.

        Returns:
            dict: On success, returns {"success": True, "message": "..."}.
                  On failure, returns {"success": False, "error": "..."}.

        Constraints:
            - The conversion job must exist.
            - The conversion job must be in a completed/terminal state before output can be attached.
            - At least one of output_file_id or artifact_id must be provided.
            - If provided, output_file_id must reference an existing file.
            - If provided, artifact_id must reference an existing export artifact and must be consistent
              with the conversion job's source file.
            - This operation updates job output linkage only; it must preserve conversion lineage.
        """
        job = self.conversion_jobs.get(job_id)
        if job is None:
            return {"success": False, "error": "Conversion job not found"}

        status = job.get("status")
        if status not in {"completed", "done", "success", "finished"}:
            return {
                "success": False,
                "error": "Conversion job must be completed before attaching output"
            }

        if output_file_id is None and artifact_id is None:
            return {
                "success": False,
                "error": "At least one of output_file_id or artifact_id must be provided"
            }

        if output_file_id is not None:
            output_file = self.files.get(output_file_id)
            if output_file is None:
                return {"success": False, "error": "Output file not found"}

            source_file = self.files.get(job["source_file_id"])
            if source_file is None:
                return {"success": False, "error": "Source file for conversion job not found"}

            if output_file["drive_id"] != source_file["drive_id"]:
                return {
                    "success": False,
                    "error": "Output file must belong to the same drive as the source file"
                }

        if artifact_id is not None:
            artifact = self.export_artifacts.get(artifact_id)
            if artifact is None:
                return {"success": False, "error": "Export artifact not found"}

            if artifact["source_file_id"] != job["source_file_id"]:
                return {
                    "success": False,
                    "error": "Export artifact does not match the conversion job source file"
                }

        if job.get("output_file_id") is not None and job["output_file_id"] != output_file_id:
            return {
                "success": False,
                "error": "Conversion job already has a different output file attached"
            }

        if output_file_id is not None:
            job["output_file_id"] = output_file_id

        return {
            "success": True,
            "message": "Conversion output attached successfully"
        }

    def create_export_artifact(
        self,
        artifact_id: str,
        source_file_id: str,
        artifact_type: str,
        format: str,
        created_at: str,
        generated_file_id: Optional[str] = None,
        location_id: Optional[str] = None,
    ) -> dict:
        """
        Register a derived artifact generated from a source file or workflow output.

        Args:
            artifact_id (str): Unique identifier for the export artifact to create.
            source_file_id (str): Identifier of the existing source file that produced the artifact.
            artifact_type (str): Type of artifact, such as "export" or "conversion_output".
            format (str): Output format of the artifact, such as "pdf" or "xlsx".
            created_at (str): Creation timestamp for the artifact.
            generated_file_id (Optional[str]): Optional file ID of the generated output file.
            location_id (Optional[str]): Optional storage or location reference for the artifact.

        Returns:
            dict: On success, {"success": True, "message": "Export artifact created successfully"}.
                  On failure, {"success": False, "error": "<reason>"}.

        Constraints:
            - artifact_id must be unique.
            - source_file_id must reference an existing file.
            - If provided, generated_file_id must reference an existing file.
            - The artifact is tracked separately from the source file and does not modify source content.
        """
        if artifact_id in self.export_artifacts:
            return {"success": False, "error": "Export artifact already exists"}

        if source_file_id not in self.files:
            return {"success": False, "error": "Source file does not exist"}

        if generated_file_id is not None and generated_file_id not in self.files:
            return {"success": False, "error": "Generated file does not exist"}

        self.export_artifacts[artifact_id] = {
            "artifact_id": artifact_id,
            "source_file_id": source_file_id,
            "generated_file_id": generated_file_id,
            "artifact_type": artifact_type,
            "format": format,
            "location_id": location_id,
            "created_at": created_at,
        }

        return {"success": True, "message": "Export artifact created successfully"}

    def link_artifact_to_file_version(self, artifact_id: str, version_id: str) -> dict:
        """
        Associate a derived export/conversion artifact with an existing file version.

        This operation preserves lineage by linking the artifact through the file version's
        source_artifact_id field.

        Args:
            artifact_id (str): The ID of the existing export artifact to link.
            version_id (str): The ID of the file version to associate with the artifact.

        Returns:
            dict: On success, {"success": True, "message": "Artifact linked to file version"}.
                  On failure, {"success": False, "error": "<reason>"}.

        Constraints:
            - Both the artifact and file version must already exist.
            - A file version may only be linked to one artifact at a time.
            - Relinking a version to a different artifact is rejected to preserve lineage.
            - Linking the same artifact again is treated as a successful no-op.
        """
        artifact = self.export_artifacts.get(artifact_id)
        if artifact is None:
            return {"success": False, "error": "Export artifact not found"}

        file_version = self.file_versions.get(version_id)
        if file_version is None:
            return {"success": False, "error": "File version not found"}

        existing_artifact_id = file_version.get("source_artifact_id")
        if existing_artifact_id is not None and existing_artifact_id != artifact_id:
            return {
                "success": False,
                "error": "File version is already linked to a different artifact",
            }

        file_version["source_artifact_id"] = artifact_id
        self.file_versions[version_id] = file_version

        return {"success": True, "message": "Artifact linked to file version"}

    def archive_file(self, file_id: str) -> dict:
        """
        Mark a file as archived or inactive without breaking its version history.

        Args:
            file_id (str): Identifier of the file to archive.

        Returns:
            dict: On success, returns:
                { "success": True, "message": "File archived successfully" }

            On failure, returns:
                { "success": False, "error": <reason> }

        Constraints:
            - The file must exist.
            - The file's identity, folder assignment, and version history must be preserved.
            - This operation must not delete the file or alter file versions.
        """
        file_info = self.files.get(file_id)
        if file_info is None:
            return {"success": False, "error": "File does not exist"}

        # Preserve file identity and version lineage; only mark archival state if supported.
        file_info["updated_at"] = file_info["updated_at"]

        # If the runtime state accepts extra metadata fields, record archival status.
        # This avoids changing core identity fields or version history.
        try:
            file_info["archived"] = True  # type: ignore[typeddict-item]
        except Exception:
            pass

        self.files[file_id] = file_info
        return {"success": True, "message": "File archived successfully"}

