def get_sharing_setting_by_target(self, target_id: str, target_type: str) -> dict:
    """
    Retrieve the sharing setting for a file or folder.

    Args:
        target_id (str): The ID of the file or folder to look up.
        target_type (str): The target kind, expected to be either "file" or "folder".

    Returns:
        dict: On success, returns:
            {
                "success": True,
                "data": Optional[SharingSettingInfo]
            }
            The data value is None if no sharing setting exists for the target.

        On failure, returns:
            {
                "success": False,
                "error": str
            }

    Constraints:
        - target_type must be either "file" or "folder".
        - The referenced file or folder must exist.
        - Sharing settings are read-only for this query and do not modify state.
    """
    if target_type not in {"file", "folder"}:
        return {"success": False, "error": "Invalid target_type; expected 'file' or 'folder'"}

    if target_type == "file":
        if target_id not in self.files:
            return {"success": False, "error": "File does not exist"}
        for sharing_setting in self.sharing_settings.values():
            if sharing_setting["file_id"] == target_id:
                return {"success": True, "data": sharing_setting}
    else:
        if target_id not in self.folders:
            return {"success": False, "error": "Folder does not exist"}
        for sharing_setting in self.sharing_settings.values():
            if sharing_setting["folder_id"] == target_id:
                return {"success": True, "data": sharing_setting}

    return {"success": True, "data": None}

